//! Complete original player-link policy DATA; no source or completion authority.
//! The host supplies the same authentic Original Analyze archive and full scope.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_reactive_reads::Failure,captured_raw_file::Config,lint::Site};
use std::{io,path::Path,sync::Arc};
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
pub struct PlayerData{sites:Vec<Site>}
impl PlayerData{pub fn metadata(&self)->&'static crate::lint::Meta{crate::player_link_policy::metadata()}pub fn sites(&self)->&[Site]{&self.sites}pub fn notes(&self)->&[String]{&[]}pub fn allow_used(&self)->&[crate::lint::AllowUse]{&[]}pub fn allow_source_digest(&self,_:&str)->Option<&[u8;20]>{None}}
struct Work<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>,peak:usize}
impl dm_analysis::policy_body_demand::WorkspaceWork for Work<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{fund::checked(self.budget,self.poll)}fn retain(&mut self,bytes:usize)->Result<(),Failure>{self.budget.charge(bytes).map_err(|m|oom(self.budget,m))}fn temporary(&mut self,bytes:usize)->Result<(),Failure>{if bytes>self.peak{self.budget.charge(bytes-self.peak).map_err(|m|oom(self.budget,m))?;self.peak=bytes;}Ok(())}fn overflow(&mut self)->Failure{oom(self.budget,"player-link workspace geometry overflow")}fn allocation_failed(&mut self)->Failure{oom(self.budget,"player-link workspace allocation refused")}fn body<'a>(&mut self,archive:&'a dm_tree::frontend::BodyArchive,ordinal:usize)->Result<dm_tree::frontend::ArchivedBody<'a>,Failure>{fund::checked(self.budget,self.poll)?;archive.parse_checked(ordinal).map_err(|error|match error{dm_tree::frontend::BodySyntaxFailure::Operational(actual)=>Failure::Operational(actual),dm_tree::frontend::BodySyntaxFailure::Syntax(error)=>Failure::Unsupported(error.message)})}}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
pub fn collect(inputs:&dm_analysis::policy_inputs::PolicyInputs,root_path:&Path,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<PlayerData,Failure>{
 fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let pending=(||{let empty=crate::scopes::LintScope::default();let scope=config.borrowed_report_scope("player_link","").unwrap_or(&empty);let mut work=Work{budget:&phase.budget,poll,peak:0};let rows=dm_analysis::player_link_native::findings_workspace_using(inputs,root_path,|relative|scope.exempt(relative),&mut work)?;
 let mut data=PlayerData{sites:Vec::new()};for row in rows{fund::checked(root,poll)?;fund::row(root,poll,&mut data.sites)?;data.sites.push(Site{rule:fund::own(root,poll,"raw_key")?,rel:fund::own(root,poll,&row.rel)?,line:u32::try_from(row.line).map_err(|_|oom(root,"player-link line overflow"))?,msg:fund::own(root,poll,crate::player_link_policy::MESSAGE)?,key:String::new(),ident:String::new()});}fund::checked(root,poll)?;Ok::<_,Failure>(data)})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.ok=pending.is_ok();drop(phase);pending
}
